def car_pooling(trips, capacity):
    events = []
    for passengers, start, end in trips:
        events.append((start, passengers))
        events.append((end, -passengers))

    events.sort()

    current = 0
    for _, delta in events:
        current += delta
        if current > capacity:
            return False

    return True

